<?php require_once __DIR__.'/../bootstrap.php';require_admin();$anime=(int)($_GET['anime_id']??0);if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);if(isset($_POST['delete']))$pdo->prepare('DELETE FROM episodes WHERE id=?')->execute([$id]);else{$num=(float)$_POST['number'];$q=$pdo->prepare($id?'UPDATE episodes SET number=?,title=?,thumbnail=?,active=? WHERE id=?':'INSERT INTO episodes(anime_id,number,title,thumbnail,active) VALUES(?,?,?,?,?)');$v=[$num,trim($_POST['title']),trim($_POST['thumbnail']),isset($_POST['active'])?1:0];if($id)$v[]=$id;else array_unshift($v,(int)$_POST['anime_id']);$q->execute($v);}header('Location: episodes.php?anime_id='.(int)$_POST['anime_id']);exit;}$where=$anime?'WHERE e.anime_id=?':'';$s=$pdo->prepare("SELECT e.*,a.title FROM episodes e JOIN anime a ON a.id=e.anime_id $where ORDER BY a.title,e.number");$s->execute($anime?[$anime]:[]);$title='Episodes — AniRead';include __DIR__.'/../includes/header.php';?><h1>Episodes</h1><p><a class="btn" href="episode-edit.php?anime_id=<?=$anime?>">Add episode</a></p><table class="table"><tr><th>Anime</th><th>Episode</th><th>Title</th><th>Active</th><th></th></tr><?php foreach($s as $e):?><tr><td><?=e($e['title'])?></td><td><?=e($e['number'])?></td><td><?=e($e['title'])?></td><td><?=(int)$e['active']?'Yes':'No'?></td><td><a class="btn alt" href="episode-edit.php?id=<?=$e['id']?>">Edit</a></td></tr><?php endforeach;?></table><?php include __DIR__.'/../includes/footer.php';
